    [Parameter] public int Id { get; set; }

    private Product? _product;
    private List<Product> _related = new();
    private bool _loading = true;
    private int _qty = 1;

    protected override async Task OnParametersSetAsync()
    {
        _loading = true;
        _qty = 1;
        await using var db = await DbFactory.CreateDbContextAsync();
        _product = await db.Products.Include(p => p.Category)
            .FirstOrDefaultAsync(p => p.Id == Id && p.IsActive);

        _related = _product == null
            ? new()
            : await db.Products.Where(p => p.CategoryId == _product.CategoryId && p.Id != _product.Id && p.IsActive)
                .Take(4).ToListAsync();
        _loading = false;
    }

    protected override async Task OnAfterRenderAsync(bool firstRender)
    {
        if (firstRender) await Cart.EnsureLoadedAsync();
    }

    private async Task AddToCart()
    {
        if (_product == null) return;
        if (_qty < 1) _qty = 1;
        var result = await Cart.AddToCartAsync(_product, _qty);
        Toast.Show(result.Message, result.Success ? "success" : "error");
    }

